components.css:
.ds-btn-primary {
  display: inline-flex; align-items: center; justify-content: center;
  height: 32px; padding: 0 12px;
  border: 0; border-radius: var(--radius-xs, 4px);
  background: var(--primary, #3e63dd);
  color: var(--primary-foreground, #ffffff);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-caption, 13px); line-height: 1.38; font-weight: 500;
  cursor: pointer;
  transition: background-color var(--duration-fast, 150ms) var(--ease-hover, cubic-bezier(0.4, 0, 0.2, 1));
}
.ds-btn-primary:hover { background: var(--primary-active, #3358d4); }
.ds-btn-primary:focus-visible { outline: none; box-shadow: var(--focus-ring, 0 0 0 3px var(--accent-a4, #e1e9ff)); }
.ds-btn-primary:disabled { opacity: var(--opacity-disabled, 0.55); cursor: default; }

.ds-btn-ghost {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 32px; padding: 0 12px;
  border: 0; border-radius: var(--radius-xs, 4px);
  background: transparent; color: var(--contrast-foreground-secondary, #5c5c5c);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-caption, 13px); line-height: 1.38;
  cursor: pointer;
  transition: background-color var(--duration-fast, 150ms) var(--ease-hover, cubic-bezier(0.4, 0, 0.2, 1));
}
.ds-btn-ghost:hover { background: var(--hover-quiet, rgba(27, 27, 27, 0.05)); color: var(--contrast-foreground, #1b1b1b); }
.ds-btn-ghost:focus-visible { outline: none; box-shadow: var(--focus-ring, 0 0 0 3px var(--accent-a4, #e1e9ff)); }

.ds-icon-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: var(--size-icon-button, 28px); height: var(--size-icon-button, 28px);
  padding: var(--icon-button-pad, 2px);
  border: 0; border-radius: var(--radius-sm, 6px);
  background: transparent; color: var(--contrast-foreground-muted, #6e6e6e);
  cursor: pointer;
  transition: background-color var(--duration-fast, 150ms) var(--ease-hover, cubic-bezier(0.4, 0, 0.2, 1));
}
.ds-icon-btn:hover { background: var(--hover-quiet, rgba(27, 27, 27, 0.05)); color: var(--contrast-foreground, #1b1b1b); }
.ds-icon-btn:focus-visible { outline: none; box-shadow: var(--focus-ring, 0 0 0 3px var(--accent-a4, #e1e9ff)); }

.ds-input {
  width: 100%; height: 32px; padding: 0 8px;
  border: var(--border-width, 1px) solid var(--border, #d0d0d0);
  border-radius: var(--radius-xs, 4px);
  background: var(--card, #ffffff);
  color: var(--contrast-foreground, #1b1b1b);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-body-md, 14px); line-height: 1.43;
  transition: border-color var(--duration-fast, 150ms) var(--ease-hover, cubic-bezier(0.4, 0, 0.2, 1));
}
.ds-input::placeholder { color: var(--placeholder, rgba(118, 118, 118, 0.62)); }
.ds-input:hover { border-color: var(--border-subtle, #dedede); }
.ds-input:focus-visible { outline: none; border-color: var(--primary, #3e63dd); box-shadow: var(--focus-ring, 0 0 0 3px var(--accent-a4, #e1e9ff)); }

.ds-nav { display: flex; flex-direction: column; gap: 2px; width: 232px; }
.ds-nav-row {
  display: block; width: 100%; height: var(--size-nav-rail, 28px);
  padding: 0 var(--space-xs, 8px);
  border: 0; border-radius: var(--radius-sm, 6px);
  background: transparent; color: var(--sidebar-foreground, #1b1b1b);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-body-md, 14px); line-height: 1.43; text-align: start;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  cursor: pointer;
  transition: background-color var(--duration-fast, 150ms) var(--ease-hover, cubic-bezier(0.4, 0, 0.2, 1));
}
.ds-nav-row:hover { background: var(--hover-quiet, rgba(27, 27, 27, 0.05)); }
.ds-nav-row.is-selected { background: var(--sidebar-selected, #e6e6e8); }
.ds-nav-row:focus-visible { outline: none; box-shadow: var(--focus-ring, 0 0 0 3px var(--accent-a4, #e1e9ff)); }

.ds-workbench {
  display: flex; flex-direction: column; min-height: 160px; padding: var(--space-md, 16px);
  border: var(--border-width, 1px) solid var(--border-subtle, #dedede);
  border-radius: var(--radius-card, 12px);
  background: var(--workbench-surface, #ffffff);
}
.ds-workbench-title {
  margin: 0; color: var(--contrast-foreground, #1b1b1b);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-title, 16px); line-height: 1.4; font-weight: 500;
}

.ds-composer {
  display: flex; flex-direction: column; justify-content: space-between; gap: 16px;
  min-height: 96px; padding: 16px;
  border: var(--border-width, 1px) solid var(--composer-border, rgba(0, 0, 0, 0.08));
  border-radius: var(--composer-radius, 32px);
  corner-shape: superellipse(1.5);
  background: var(--workbench-surface, #ffffff);
  box-shadow: var(--composer-shadow, 0 12px 28px -18px rgba(0, 0, 0, 0.4));
}
.ds-composer-placeholder {
  color: var(--placeholder, rgba(118, 118, 118, 0.62));
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-body-md, 14px); line-height: 1.43;
}
.ds-composer-actions { display: flex; align-items: center; justify-content: flex-end; gap: var(--space-xs, 8px); }
.ds-composer-model {
  color: var(--contrast-foreground-muted, #6e6e6e);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-caption, 13px); line-height: 1.38;
}
.ds-composer-send {
  display: inline-flex; align-items: center; justify-content: center;
  width: var(--size-composer-control, 32px); height: var(--size-composer-control, 32px);
  border: 0; border-radius: var(--radius-pill, 9999px);
  background: var(--primary, #3e63dd); color: var(--primary-foreground, #ffffff);
  cursor: pointer;
  transition: background-color var(--duration-fast, 150ms) var(--ease-hover, cubic-bezier(0.4, 0, 0.2, 1));
}
.ds-composer-send:hover { background: var(--primary-active, #3358d4); }
.ds-composer-send:focus-visible { outline: none; box-shadow: var(--focus-ring, 0 0 0 3px var(--accent-a4, #e1e9ff)); }

.ds-badge {
  display: inline-flex; align-items: center;
  padding: 2px var(--space-xs, 8px);
  border-radius: var(--radius-pill, 9999px);
  background: var(--info-bg, #edf2fe); color: var(--primary-active, #3358d4);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-eyebrow, 12px); line-height: 1.33; font-weight: 500;
  margin-inline-end: 6px;
}
.ds-badge-success { background: var(--success-bg, #e3f2e8); color: var(--success, #15803d); }

.ds-bubble-wrap { display: flex; justify-content: flex-end; }
.ds-bubble {
  max-width: 90%; padding: var(--space-xs, 8px) var(--space-sm, 12px);
  border-radius: var(--radius-md, 8px);
  background: var(--user-prompt-background, #e8e8ea);
  color: var(--contrast-foreground, #1b1b1b);
  font-family: var(--font-sans, "anthropic-sans", -apple-system, "Segoe UI", "PingFang SC", sans-serif);
  font-size: var(--text-body-md, 14px); line-height: 1.5;
}
